import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# CUDA kernel and wrapper compiled at import time
_src = r'''
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void mse_kernel(const __half* __restrict__ pred,
                           const __half* __restrict__ target,
                           float* __restrict__ sum,
                           size_t N) {
    size_t idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < N) {
        float diff = __half2float(pred[idx]) - __half2float(target[idx]);
        atomicAdd(sum, diff * diff);
    }
}

at::Tensor mse_fp16(at::Tensor pred, at::Tensor target) {
    TORCH_CHECK(pred.is_cuda(), "pred must be CUDA");
    TORCH_CHECK(target.is_cuda(), "target must be CUDA");
    TORCH_CHECK(pred.scalar_type() == at::ScalarType::Half,
                "pred must be float16");
    TORCH_CHECK(target.scalar_type() == at::ScalarType::Half,
                "target must be float16");
    TORCH_CHECK(pred.sizes() == target.sizes(),
                "pred and target must have the same shape");

    const size_t N = pred.numel();

    // single-element float32 accumulator on device
    auto sum = torch::zeros({1},
                            torch::device(pred.device())
                            .dtype(at::ScalarType::Float));

    const int threads = 256;
    const int blocks = static_cast<int>((N + threads - 1) / threads);

    mse_kernel<<<blocks, threads>>>(
        pred.data_ptr<__half>(),
        target.data_ptr<__half>(),
        sum.data_ptr<float>(),
        N);
    cudaDeviceSynchronize();

    float sum_h = sum.item<float>();
    float mean_f = sum_h / static_cast<float>(N);

    // produce a 0‑dim float16 tensor on the same device
    auto out = torch::tensor(static_cast<at::Half>(mean_f),
                             torch::dtype(at::ScalarType::Half)
                             .device(pred.device()));
    return out;
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("mse_fp16", &mse_fp16, "Mean Squared Error for float16 tensors (CUDA)");
}
'''

# compile the inline extension
_mse_ext = load_inline(name='mse_fp16_ext',
                       cpp_sources='',
                       cuda_sources=_src,
                       functions=['mse_fp16'],
                       verbose=False)

class ModelNew(nn.Module):
    """Drop‑in replacement for the reference Model using the custom CUDA kernel."""
    def __init__(self):
        super().__init__()

    def forward(self, predictions: torch.Tensor, targets: torch.Tensor) -> torch.Tensor:
        return _mse_ext.mse_fp16(predictions, targets)

def get_inputs():
    scale = torch.rand(()).cuda()
    # large tensors matching the reference shapes, in float16
    preds = torch.rand(32768, 32768, device='cuda', dtype=torch.float16) * scale
    targs = torch.rand(32768, 32768, device='cuda', dtype=torch.float16)
    return [preds, targs]

def get_init_inputs():
    return []
